    nodes = set([(Ax, Ay), (Bx, By)])
    for x1, y1, x2, y2 in trenches:
        nodes.add((x1, y1))
        nodes.add((x2, y2))

    graph = {node: [] for node in nodes}
    for x1, y1, x2, y2 in trenches + [(Ax, Ay, Ax, Ay), (Bx, By, Bx, By)]:
        if x1 == x2:
            for y in range(min(y1, y2), max(y1, y2) + 1):
                graph[(x1, y)].append(((x1, y + 1), 1))
                graph[(x1, y + 1)].append(((x1, y), 1))
        else:
            for x in range(min(x1, x2), max(x1, x2) + 1):
                graph[(x, y1)].append(((x + 1, y1), 1))
                graph[(x + 1, y1)].append(((x, y1), 1))

